#include <iostream>
#include <vector>
#include <ranges>

int main() {
    using namespace std;
    unsigned N, K;
    cin >> N >> K;
    vector<unsigned> A(N);
    for (auto&& a : A) cin >> a;

    // A[i] != X[i] となる最大の i は、j < i かつ A[j] > A[i] なる j が存在する最大の j
    unsigned prefix_max{}, max_i{};
    for (const auto& [i, a] : A | views::enumerate) {
        prefix_max = max(a, prefix_max);
        if (prefix_max > a) max_i = i;
    }

    // A[i] != X[i] となる最小の i は、i < j かつ A[i] > A[j] なる j が存在する最小の j
    unsigned suffix_min{N}, min_i{N};
    for (const auto& [i, a] : A | views::enumerate | views::reverse) {
        suffix_min = min(a, suffix_min);
        if (suffix_min < a) min_i = i;
    }

    cout << (K + min_i > max_i ? "Yes" : "No") << endl;
    return 0;
}
